/** Questions for one chapter (e.g. "sets-inequalities"). */
export function examQuestionsByChapter(chapter: string): ExamQuestion[] {
  return EXAM_QUESTIONS.filter((q) => q.chapter === chapter);
}

/**
 * Cross-listed for Functions: tagged under another chapter in the bank
 * (chapter tags below are unchanged) but solved with a Functions-chapter
 * skill — slope-as-tan, linear-function equations/intersections, symmetry,
 * or linear-in-n form. Each carries the Functions lesson it drills.
 */
export const FUNCTIONS_CROSS_LIST: { id: string; why: string }[] = [
  { id: "E1-14", why: "Inclination of \\(y = \\sqrt{3}x + 10\\): slope is \\(\\tan\\theta\\) — trig definitions + special values (lessons 1–2)." },
  { id: "E1-28", why: "Intersection of \\(y = 2x+1\\) with \\(x+y+1=0\\): solving \\(f(x) = g(x)\\) for linear functions (lesson 16)." },
  { id: "E2-6", why: "Q symmetric about the x-axis: symmetry reading that parity work builds on (lesson 16)." },
  { id: "E2-13", why: "Slope through two points: sign of slope = direction of a linear function (lesson 16)." },
  { id: "E2-14", why: "\\(\\sin\\alpha\\) for a line through \\(P(1,3)\\): terminal-side trig definitions (lesson 2)." },
  { id: "E2-17", why: "Inclination \\(45^\\circ\\) through \\((0,2)\\): \\(\\tan45^\\circ = 1\\) gives \\(y = x+2\\) (lessons 1, 16)." },
  { id: "E2-24", why: "Intersection of two lines: solving \\(f(x) = g(x)\\) (lesson 16)." },
  { id: "E3-9", why: "Slope through \\(A(-1,1)\\), \\(B(2,3)\\): sign of slope = direction of a linear function (lesson 16)." },
  { id: "E3-14", why: "Inclination \\(60^\\circ\\): slope \\(= \\tan60^\\circ = \\sqrt{3}\\) (lesson 1)." },
  { id: "E3-17", why: "\\(a_n = 2n-1\\): linear-in-\\(n\\) form, monotonic like a linear function (lesson 16)." },
  { id: "E3-19", why: "Point-slope equation: writing a linear function from slope + point (lesson 16)." },
  { id: "E3-27", why: "Intersection of two lines: solving \\(f(x) = g(x)\\) (lesson 16)." },
];

/** Functions page set: 58 core (chapter tag) + 12 cross-listed (skill match). */
export function examQuestionsForFunctions(): { core: ExamQuestion[]; cross: { q: ExamQuestion; why: string }[] } {
  const whyById = new Map(FUNCTIONS_CROSS_LIST.map((c) => [c.id, c.why]));
  return {
    core: EXAM_QUESTIONS.filter((q) => q.chapter === "functions"),
    cross: EXAM_QUESTIONS.filter((q) => whyById.has(q.id)).map((q) => ({
      q,
      why: whyById.get(q.id) ?? "",
    })),
  };
}

/** Count of questions per chapter, in MATH_SYLLABUS order. */
export function examChapterCounts(): { chapter: string; count: number }[] {
  const map = new Map<string, number>();
  for (const q of EXAM_QUESTIONS) map.set(q.chapter, (map.get(q.chapter) ?? 0) + 1);
  return [...map.entries()].map(([chapter, count]) => ({ chapter, count }));
}

